const course: DeepCourse = {"slug":"writing-for-clients","title":"Writing for Clients Who Pay","premium":true,"previewCount":3,"chunks":[{"kind":"html","value":"<section id=\"the-job\" class=\"px-5 pt-28 md:px-8 md:pt-40\"><div class=\"mx-auto max-w-5xl\"><p class=\"eyebrow\">Career skill · Pro</p><h1 class=\"display-lg mt-4\">Writing for Clients Who Pay<span class=\"dot\" aria-hidden=\"true\">.</span></h1><p class=\"lede mt-5 max-w-xl\">Research, write, edit, and hand over useful words without becoming a cheap content machine.</p><div class=\"mt-8 flex flex-wrap gap-2.5\"><span class=\"inline-flex rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold bg-leaf-wash text-leaf border-transparent\">Premium course</span><span class=\"inline-flex rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold bg-accent-soft text-accent-deep border-transparent\">8 modules</span><span class=\"inline-flex rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold border\">6-question quiz</span></div></div></section><nav aria-label=\"Course sections\" class=\"sticky top-16 z-20 border-b border-line bg-paper/90 backdrop-blur-md\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-6xl\"><ul class=\"-mx-1 flex gap-1 overflow-x-auto py-2.5 [scrollbar-width:none] [&amp;::-webkit-scrollbar]:hidden\"><li><a href=\"#the-job\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">The job</a></li><li><a href=\"#tools\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Tools</a></li><li><a href=\"#modules\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Modules</a></li><li><a href=\"#rates\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Rates</a></li><li><a href=\"#first-client\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">First client</a></li><li><a href=\"#quiz\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Quiz</a></li><li><a href=\"#glossary\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Glossary</a></li><li><a href=\"#red-flags\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Red flags</a></li><li><a href=\"#faq\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">FAQ</a></li></ul></div></nav><section class=\"px-5 pt-10 md:px-8\"><div class=\"mx-auto max-w-5xl\"><div id=\"plain-words\" class=\"rounded-2xl border border-line bg-card p-6 shadow-tile sm:p-7\"><p class=\"eyebrow\">In plain words</p><p class=\"mt-3 max-w-3xl text-[1.0625rem] leading-[1.75] text-ink\">Content writing pays when you’re fast and consistent — which comes from process, not talent. This course gives you the brief-to-draft-to-edit system and teaches you to sound like the client, not like a robot.</p><div class=\"mt-6 grid gap-5 sm:grid-cols-2\"><div><p class=\"eyebrow text-muted\">This is for you if</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">You already write decently and want to get paid for it without drowning in endless revision rounds.</p></div><div><p class=\"eyebrow text-muted\">You walk away with</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">A repeatable writing process, brief and outline templates, and editing habits that cut revisions in half.</p></div></div></div></div></section>"},{"kind":"html","value":"<section id=\"the-job\" class=\"px-5 py-16 md:px-8\"><div class=\"mx-auto grid max-w-5xl gap-10 md:grid-cols-2\"><div><p class=\"eyebrow\">The job</p><h2>A writer is paid to make a decision easier.</h2><p>Clients hire a content writer VA to turn messy expertise, product knowledge, and customer questions into a clear page, email, article, or case study. The deliverable is not “words.” It is a reader who understands what to do next.</p></div><div><p class=\"eyebrow\">The work</p><p>You will read briefs, interview sources, build outlines, draft in the client voice, check claims, handle feedback, and protect a publishing schedule. Strong writing work includes research and judgment; typing is the visible last step.</p><p>For a Filipino VA, the useful edge is calm English, clean process, and showing the client exactly how you reached a claim. Do not sell “AI content.” Sell reliable research and a draft that requires less managing.</p></div></div></section>"},{"kind":"slot","value":"MODULES","wrappers":[{"tag":"section","class":"px-5 py-16 md:px-8"},{"tag":"div","class":"mx-auto max-w-5xl"}]},{"kind":"html","value":"<div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"keep-learning\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Keep learning<span class=\"dot\" aria-hidden=\"true\">.</span></h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Hand-picked and free. These open in a new tab — official docs, academies and channels that go deeper on what this track teaches. No affiliate links, no sign-up walls.</p><ul class=\"mt-8 grid gap-3 sm:grid-cols-2\"><li class=\"h-full\"><a href=\"https://hemingwayapp.com/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Hemingway Editor</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Edit every draft in it until the grade drops below 9.</p></a></li><li class=\"h-full\"><a href=\"https://copyblogger.com/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Copyblogger</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Two decades of free copywriting fundamentals.</p></a></li><li class=\"h-full\"><a href=\"https://www.nngroup.com/topic/writing-web/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Nielsen Norman Group — writing for the web</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Research-backed rules for headlines, scanning and structure.</p></a></li></ul></section></div>"},{"kind":"html","value":"<section id=\"tools\" class=\"px-5 py-16 md:px-8\"><div class=\"mx-auto max-w-5xl\"><p class=\"eyebrow\">Tools</p><h2>Learn the stack. Do not worship it.</h2><p>Google Docs is usually the source of truth. Use a spreadsheet or Airtable for the content calendar, Grammarly or Hemingway for a final pass rather than a brain, and approved AI tools for structure—not facts or final voice.</p><div class=\"grid gap-4 md:grid-cols-3\"><div class=\"rounded-2xl border p-5\"><h3>Google Docs</h3><p>Brief boxes, comments, Suggesting mode, and named versions make feedback reviewable.</p></div><div class=\"rounded-2xl border p-5\"><h3>Ahrefs / Semrush</h3><p>Use them to find search intent and competing pages, then write something those pages missed.</p></div><div class=\"rounded-2xl border p-5\"><h3>Notion / Airtable</h3><p>Track topic, brief, source, draft, approval, publish date, and update date in one view.</p></div></div></div></section>"},{"kind":"html","value":"<section id=\"rates\" class=\"px-5 py-16 md:px-8\"><div class=\"mx-auto max-w-5xl\"><p class=\"eyebrow\">Rates</p><h2>Price the outcome and the risk.</h2><p>Entry work often lands around US$0.05–0.12 per word or US$12–25 per hour. Research-heavy B2B, case studies, email strategy, SEO briefs, and editing rise faster because they include judgment. Quote after you know the sources, length, approval rounds, and whether the client expects strategy.</p><p>If an 1,000-word “article” needs two interviews, original research, CMS formatting, images, and three rounds of feedback, it is not a per-word typing job. Break out the work or set a project minimum.</p></div></section>"},{"kind":"html","value":"<section id=\"first-client\" class=\"px-5 py-16 md:px-8\"><div class=\"mx-auto max-w-5xl\"><p class=\"eyebrow\">First client</p><h2>Make a small, believable promise.</h2><p>Make three samples for one kind of client: an article, a service page, and an email. Give every sample a brief and source log. A client can forgive unpublished work; they cannot infer a process you did not show.</p><ol><li>Pick one industry you can research without pretending to be an expert.</li><li>Write a short brief with reader, decision, format, sources, word count, and approval owner.</li><li>Publish three linkable samples with a small “why I wrote it this way” note.</li></ol></div></section>"},{"kind":"html","value":"<section id=\"red-flags\" class=\"px-5 py-16 md:px-8\"><div class=\"mx-auto max-w-5xl\"><p class=\"eyebrow\">Red flags</p><h2>Walk away early.</h2><div class=\"grid gap-4 md:grid-cols-2\"><div class=\"rounded-2xl border border-red-200 p-5\"><h3>Unlimited revisions</h3><p>A client who cannot define approval cannot promise a finish line. Include two rounds and price additional rounds.</p></div><div class=\"rounded-2xl border border-red-200 p-5\"><h3>“Use AI and make it human”</h3><p>This usually means low budget, no source material, and a request to hide the process. Ask for voice examples and an AI policy.</p></div><div class=\"rounded-2xl border border-red-200 p-5\"><h3>No source for claims</h3><p>Do not invent proof for a product or health, finance, legal, or performance claim. Request approved sources.</p></div><div class=\"rounded-2xl border border-red-200 p-5\"><h3>Paid test article</h3><p>A short, bounded test can be fair. A publishable 1,500-word piece for free is a rejected budget.</p></div><div class=\"rounded-2xl border border-red-200 p-5\"><h3>Word count without goal</h3><p>A long article is not a strategy. Ask what reader action or ranking problem the piece is meant to solve.</p></div><div class=\"rounded-2xl border border-red-200 p-5\"><h3>Silent stakeholder</h3><p>Ask who has final approval before drafting. Otherwise a late founder comment can restart the whole job.</p></div></div></div></section>"},{"kind":"slot","value":"QUIZ","wrappers":[{"tag":"section","class":"px-5 py-16 md:px-8"},{"tag":"div","class":"mx-auto max-w-5xl"}]},{"kind":"slot","value":"GLOSSARY","wrappers":[{"tag":"section","class":"px-5 py-16 md:px-8"},{"tag":"div","class":"mx-auto max-w-5xl"}]},{"kind":"html","value":"<section class=\"px-5 py-20 md:px-8\"><div class=\"mx-auto max-w-5xl rounded-3xl bg-ink p-8 text-paper md:p-12\"><p class=\"eyebrow\">Your next move</p><h2>Do one real content writer va task this week.</h2><p>Choose a real business, make one defensible brief, and write the version that helps its reader decide. Save the source log. That is a stronger beginning than a hundred generic prompts.</p><a class=\"button\" href=\"/courses\">Build your proof</a></div></section>"}],"modules":[{"n":1,"title":"Read the brief like a contract","outcome":"Turn a loose request into an agreed deliverable.","badges":["Practice","Client-ready"],"minutes":5,"html":"<div class=\"rounded-xl border border-teal-pale bg-teal-wash/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The job</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Turn a loose request into an agreed deliverable.</p></div><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">A brief needs reader, problem, format, goal, length, source material, deadline, examples, and approver. Missing one changes the work.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use a brief box in Google Docs and freeze the version before drafting.</p><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — A founder says: “Write a thought-leadership article about AI.”</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You reply: “I understand this as an 800-word LinkedIn article for operations leaders, showing one practical AI workflow and leading to a discovery call. Please confirm the audience, one client example we can name, and final approver.”</p></div><div class=\"rounded-xl border border-line-2 bg-card p-4 sm:p-5\"><p class=\"eyebrow mb-3 text-muted\">Try it now — tick each step as you do it</p><ul class=\"space-y-2.5\" data-checklist><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">List the deliverable and reader.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Write the one action the reader should take.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Name the source material and the approver.</span></label></li></ul></div>","quiz":[{"q":"A client asks what you got out of “Read the brief like a contract”. The honest answer is:","options":["Turn a loose request into an agreed deliverable.","Build a source log that survives a client question.","Create an outline that earns its length.","Run an editing sequence that removes real weaknesses."],"answer":0,"explain":"That is the outcome this module is building. If it does not feel true yet, run the exercise once more — the later modules assume it."},{"q":"One of these outcomes belongs to a completely different course. Which one?","options":["Build a source log that survives a client question.","Write clean first drafts without flattening the client voice.","Package proof, rates, and ongoing work around a repeatable process.","You can spot the standard scams in under a minute and you know what a bad-but-legal client looks like before you sign."],"answer":3,"explain":"That one is from “The Complete VA Starter”. The other three are all stops on this course's path — worth noticing how they stack."},{"q":"In “Read the brief like a contract”, what do you do first?","options":["Write the one action the reader should take.","Name the source material and the approver.","List the deliverable and reader."],"answer":2,"explain":"Order protects the outcome here: “List the deliverable and reader.” comes before everything else, or the rest is guesswork."}]},{"n":2,"title":"Research until the draft has teeth","outcome":"Build a source log that survives a client question.","badges":["Practice","Client-ready"],"minutes":5,"html":"<div class=\"rounded-xl border border-teal-pale bg-teal-wash/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The job</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Build a source log that survives a client question.</p></div><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Generic copy comes from generic sources. Start with the client’s product docs, customer calls, reviews, support tickets, and interviews; use reputable external sources to frame, not decorate.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Keep URL, date, quote, claim supported, and permission status in a simple table.</p><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — A payroll app claims it saves “hours every week.”</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You find three support tickets about payroll corrections, a customer quote, and the product’s actual workflow. The article can now say who benefits, from which task, under what condition—without inventing a number.</p></div><div class=\"rounded-xl border border-line-2 bg-card p-4 sm:p-5\"><p class=\"eyebrow mb-3 text-muted\">Try it now — tick each step as you do it</p><ul class=\"space-y-2.5\" data-checklist><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Collect two primary sources.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Extract three concrete details.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Mark every statistic that needs a link.</span></label></li></ul></div>","quiz":[{"q":"Which of these is the outcome “Research until the draft has teeth” is building toward?","options":["Turn a loose request into an agreed deliverable.","Write clean first drafts without flattening the client voice.","Build a source log that survives a client question.","Use AI for reversible work while keeping responsibility."],"answer":2,"explain":"That is the outcome this module is building. If it does not feel true yet, run the exercise once more — the later modules assume it."},{"q":"One of these outcomes belongs to a completely different course. Which one?","options":["Create an outline that earns its length.","Use AI for reversible work while keeping responsibility.","Package proof, rates, and ongoing work around a repeatable process.","You can run one-to-ones, give feedback that changes behaviour, and handle underperformance without either avoiding it or blowing it up."],"answer":3,"explain":"That one is from “Becoming an Operations Lead”. The other three are all stops on this course's path — worth noticing how they stack."},{"q":"In “Research until the draft has teeth”, what do you do first?","options":["Collect two primary sources.","Mark every statistic that needs a link.","Extract three concrete details."],"answer":0,"explain":"Order protects the outcome here: “Collect two primary sources.” comes before everything else, or the rest is guesswork."}]},{"n":3,"title":"Outline for a reader, not a keyword tool","outcome":"Create an outline that earns its length.","badges":["Practice","Client-ready"],"minutes":5,"html":"<div class=\"rounded-xl border border-teal-pale bg-teal-wash/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The job</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Create an outline that earns its length.</p></div><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Search intent tells you the question; it does not write the answer. Use the outline to sequence the reader from their current confusion to a useful decision.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use search results, customer language, and a one-sentence promise. Do not copy competitor headings.</p><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — The keyword is “how to reduce invoice errors.”</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Your outline opens with the expensive symptom, explains the three common failure points, gives a weekly check, and ends with the point where a business needs a system rather than another reminder.</p></div><div class=\"rounded-xl border border-line-2 bg-card p-4 sm:p-5\"><p class=\"eyebrow mb-3 text-muted\">Try it now — tick each step as you do it</p><ul class=\"space-y-2.5\" data-checklist><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Write the reader question at the top.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Give every heading a job.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Delete headings that repeat an earlier answer.</span></label></li></ul></div>","quiz":[{"q":"You just finished “Outline for a reader, not a keyword tool”. What should you now be able to do?","options":["Create an outline that earns its length.","Run an editing sequence that removes real weaknesses.","Build a source log that survives a client question.","Turn subjective comments into a clear revision plan."],"answer":0,"explain":"That is the outcome this module is building. If it does not feel true yet, run the exercise once more — the later modules assume it."},{"q":"One of these outcomes belongs to a completely different course. Which one?","options":["Turn a loose request into an agreed deliverable.","Set a useful hypothesis and isolate a variable so results improve the next send rather than decorate a report.","Build a source log that survives a client question.","Package proof, rates, and ongoing work around a repeatable process."],"answer":1,"explain":"That one is from “Email Marketing VA”. The other three are all stops on this course's path — worth noticing how they stack."},{"q":"In “Outline for a reader, not a keyword tool”, what do you do first?","options":["Give every heading a job.","Write the reader question at the top.","Delete headings that repeat an earlier answer."],"answer":1,"explain":"Order protects the outcome here: “Write the reader question at the top.” comes before everything else, or the rest is guesswork."}]},{"n":4,"title":"Draft in a voice someone can recognise","outcome":"Write clean first drafts without flattening the client voice.","badges":["Practice","Client-ready"],"minutes":5,"html":"<div class=\"rounded-xl border border-teal-pale bg-teal-wash/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The job</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Write clean first drafts without flattening the client voice.</p></div><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Voice is repeated choices: sentence length, proof level, humor, vocabulary, and what the brand refuses to claim. Build a small voice sheet from approved work.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use Docs comments for voice examples and a swipe file only for structure, never stolen wording.</p><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — A warm founder brand needs a launch email.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Instead of “We are thrilled to announce,” you use the founder’s plain language, a customer problem from support, one useful detail, and a CTA that sounds like a person wrote it.</p></div><div class=\"rounded-xl border border-line-2 bg-card p-4 sm:p-5\"><p class=\"eyebrow mb-3 text-muted\">Try it now — tick each step as you do it</p><ul class=\"space-y-2.5\" data-checklist><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Collect five approved voice examples.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Write three opening options.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Choose the opening that makes a specific promise.</span></label></li></ul></div>","quiz":[{"q":"A client asks what you got out of “Draft in a voice someone can recognise”. The honest answer is:","options":["Build a source log that survives a client question.","Use AI for reversible work while keeping responsibility.","Write clean first drafts without flattening the client voice.","Create an outline that earns its length."],"answer":2,"explain":"That is the outcome this module is building. If it does not feel true yet, run the exercise once more — the later modules assume it."},{"q":"One of these outcomes belongs to a completely different course. Which one?","options":["You can report to a founder in a way that earns you decision rights, and you can say no without sounding like you are refusing work.","Package proof, rates, and ongoing work around a repeatable process.","Create an outline that earns its length.","Turn a loose request into an agreed deliverable."],"answer":0,"explain":"That one is from “Becoming an Operations Lead”. The other three are all stops on this course's path — worth noticing how they stack."},{"q":"In “Draft in a voice someone can recognise”, what do you do first?","options":["Choose the opening that makes a specific promise.","Collect five approved voice examples.","Write three opening options."],"answer":1,"explain":"Order protects the outcome here: “Collect five approved voice examples.” comes before everything else, or the rest is guesswork."}]},{"n":5,"title":"Edit without polishing the wrong problem","outcome":"Run an editing sequence that removes real weaknesses.","badges":["Practice","Client-ready"],"minutes":5,"html":"<div class=\"rounded-xl border border-teal-pale bg-teal-wash/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The job</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Run an editing sequence that removes real weaknesses.</p></div><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Edit the argument before grammar. Then cut repetition, simplify sentences, verify facts, and finally inspect links, names, formatting, and CTA.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use read-aloud, version history, and a separate factual checklist.</p><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — A 1,200-word draft feels “fine” but drags.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You remove the generic introduction, merge three similar paragraphs, replace an unsupported superlative with a customer quote, and shorten the piece to 820 words with a clearer next step.</p></div><div class=\"rounded-xl border border-line-2 bg-card p-4 sm:p-5\"><p class=\"eyebrow mb-3 text-muted\">Try it now — tick each step as you do it</p><ul class=\"space-y-2.5\" data-checklist><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Check the reader promise.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Cut one third before line editing.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Read the final draft aloud.</span></label></li></ul></div>","quiz":[{"q":"Which of these is the outcome “Edit without polishing the wrong problem” is building toward?","options":["Turn a loose request into an agreed deliverable.","Create an outline that earns its length.","Run an editing sequence that removes real weaknesses.","Use AI for reversible work while keeping responsibility."],"answer":2,"explain":"That is the outcome this module is building. If it does not feel true yet, run the exercise once more — the later modules assume it."},{"q":"One of these outcomes belongs to a completely different course. Which one?","options":["Create an outline that earns its length.","Build a source log that survives a client question.","Turn subjective comments into a clear revision plan.","You can spot the standard scams in under a minute and you know what a bad-but-legal client looks like before you sign."],"answer":3,"explain":"That one is from “The Complete VA Starter”. The other three are all stops on this course's path — worth noticing how they stack."},{"q":"In “Edit without polishing the wrong problem”, what do you do first?","options":["Cut one third before line editing.","Read the final draft aloud.","Check the reader promise."],"answer":2,"explain":"Order protects the outcome here: “Check the reader promise.” comes before everything else, or the rest is guesswork."}]},{"n":6,"title":"Use AI without handing it the steering wheel","outcome":"Use AI for reversible work while keeping responsibility.","badges":["Practice","Client-ready"],"minutes":5,"html":"<div class=\"rounded-xl border border-teal-pale bg-teal-wash/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The job</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Use AI for reversible work while keeping responsibility.</p></div><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">AI can help list questions, compare outline gaps, clean a transcript, or create alternatives. It cannot own a confidential source, a factual claim, or a client voice.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use only an approved account and keep a note of source and disclosure rules.</p><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — You need five angles for a newsletter from an interview transcript.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You ask for possible angles, choose one based on the brief, verify every claim against the transcript, and write the opening yourself. The model helped with breadth; you own the judgment.</p></div><div class=\"rounded-xl border border-line-2 bg-card p-4 sm:p-5\"><p class=\"eyebrow mb-3 text-muted\">Try it now — tick each step as you do it</p><ul class=\"space-y-2.5\" data-checklist><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Check the client AI policy.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Never paste unapproved confidential material.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Verify each useful output against a source.</span></label></li></ul></div>","quiz":[{"q":"You just finished “Use AI without handing it the steering wheel”. What should you now be able to do?","options":["Write clean first drafts without flattening the client voice.","Build a source log that survives a client question.","Use AI for reversible work while keeping responsibility.","Package proof, rates, and ongoing work around a repeatable process."],"answer":2,"explain":"That is the outcome this module is building. If it does not feel true yet, run the exercise once more — the later modules assume it."},{"q":"One of these outcomes belongs to a completely different course. Which one?","options":["Package proof, rates, and ongoing work around a repeatable process.","Set a useful hypothesis and isolate a variable so results improve the next send rather than decorate a report.","Turn a loose request into an agreed deliverable.","Create an outline that earns its length."],"answer":1,"explain":"That one is from “Email Marketing VA”. The other three are all stops on this course's path — worth noticing how they stack."},{"q":"In “Use AI without handing it the steering wheel”, what do you do first?","options":["Never paste unapproved confidential material.","Check the client AI policy.","Verify each useful output against a source."],"answer":1,"explain":"Order protects the outcome here: “Check the client AI policy.” comes before everything else, or the rest is guesswork."}]},{"n":7,"title":"Handle feedback and revisions professionally","outcome":"Turn subjective comments into a clear revision plan.","badges":["Practice","Client-ready"],"minutes":5,"html":"<div class=\"rounded-xl border border-teal-pale bg-teal-wash/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The job</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Turn subjective comments into a clear revision plan.</p></div><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Feedback is data, not a verdict. Group comments into factual, strategic, voice, and preference changes; identify the final decision-maker before touching the draft.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use Suggesting mode and a revision note that records what changed and what needs a call.</p><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Marketing says “make it more exciting”; legal says “remove the claim.”</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You remove the unsupported claim, offer two evidence-based openings, and ask the accountable approver which reader promise matters. You do not try to split the difference invisibly.</p></div><div class=\"rounded-xl border border-line-2 bg-card p-4 sm:p-5\"><p class=\"eyebrow mb-3 text-muted\">Try it now — tick each step as you do it</p><ul class=\"space-y-2.5\" data-checklist><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Sort comments by type.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Answer factual questions with sources.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Ask one decision question for contradictory notes.</span></label></li></ul></div>","quiz":[{"q":"A client asks what you got out of “Handle feedback and revisions professionally”. The honest answer is:","options":["Turn subjective comments into a clear revision plan.","Run an editing sequence that removes real weaknesses.","Use AI for reversible work while keeping responsibility.","Build a source log that survives a client question."],"answer":0,"explain":"That is the outcome this module is building. If it does not feel true yet, run the exercise once more — the later modules assume it."},{"q":"One of these outcomes belongs to a completely different course. Which one?","options":["Match the platform to the job","Build a source log that survives a client question.","Use AI for reversible work while keeping responsibility.","Turn a loose request into an agreed deliverable."],"answer":0,"explain":"That one is from “Web Development & No-Code VA”. The other three are all stops on this course's path — worth noticing how they stack."},{"q":"In “Handle feedback and revisions professionally”, what do you do first?","options":["Ask one decision question for contradictory notes.","Answer factual questions with sources.","Sort comments by type."],"answer":2,"explain":"Order protects the outcome here: “Sort comments by type.” comes before everything else, or the rest is guesswork."}]},{"n":8,"title":"Sell a writing system, not a document","outcome":"Package proof, rates, and ongoing work around a repeatable process.","badges":["Practice","Client-ready"],"minutes":5,"html":"<div class=\"rounded-xl border border-teal-pale bg-teal-wash/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The job</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Package proof, rates, and ongoing work around a repeatable process.</p></div><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">A dependable monthly writer creates a calendar, gathers inputs, drafts early, manages approvals, publishes, and reports what needs updating. That is more valuable than a random pile of posts.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Use a content tracker and a simple monthly update with published links, work in progress, and decisions needed.</p><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — A client wants four articles and four emails each month.</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">You propose an intake date, outline approval date, two revision rounds, CMS handoff, and a monthly review. The calendar prevents the client’s late input from becoming your emergency.</p></div><div class=\"rounded-xl border border-line-2 bg-card p-4 sm:p-5\"><p class=\"eyebrow mb-3 text-muted\">Try it now — tick each step as you do it</p><ul class=\"space-y-2.5\" data-checklist><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Build a three-sample portfolio.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Track actual time by stage.</span></label></li><li><label class=\"flex cursor-pointer items-start gap-3\"><input type=\"checkbox\" data-check class=\"mt-1 h-4 w-4 shrink-0 rounded\" style=\"accent-color: var(--color-accent)\"/><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Offer a small monthly pilot with clear scope.</span></label></li></ul></div>","quiz":[{"q":"Which of these is the outcome “Sell a writing system, not a document” is building toward?","options":["Run an editing sequence that removes real weaknesses.","Create an outline that earns its length.","Turn subjective comments into a clear revision plan.","Package proof, rates, and ongoing work around a repeatable process."],"answer":3,"explain":"That is the outcome this module is building. If it does not feel true yet, run the exercise once more — the later modules assume it."},{"q":"One of these outcomes belongs to a completely different course. Which one?","options":["Create an outline that earns its length.","Build a source log that survives a client question.","You can write a role, run a paid test task, and choose someone on evidence rather than on interview charm.","Turn a loose request into an agreed deliverable."],"answer":2,"explain":"That one is from “Becoming an Operations Lead”. The other three are all stops on this course's path — worth noticing how they stack."},{"q":"In “Sell a writing system, not a document”, what do you do first?","options":["Build a three-sample portfolio.","Offer a small monthly pilot with clear scope.","Track actual time by stage."],"answer":0,"explain":"Order protects the outcome here: “Build a three-sample portfolio.” comes before everything else, or the rest is guesswork."}]}],"quiz":[{"q":"A brief says “write an article about AI.” What should you do first?","options":["Start researching competitors","Confirm reader, goal, format, source, and approver","Ask an AI tool for an outline","Quote by word count"],"answer":1,"explain":"The missing decisions change every other part of the work."},{"q":"What makes a claim credible in client content?","options":["A confident tone","A competitor also said it","A source the client can review","A longer sentence"],"answer":2,"explain":"The writer owns traceability, not just attractive phrasing."},{"q":"When is AI useful for a writer?","options":["As final author","For reversible structure and question generation","For confidential source uploads","For factual approval"],"answer":1,"explain":"Use it where you can verify and revise the result."},{"q":"What is the first editing pass?","options":["Commas","Fonts","Argument and reader promise","SEO plugin score"],"answer":2,"explain":"A grammatically clean draft can still fail the reader."},{"q":"How do you handle conflicting feedback?","options":["Average the comments","Follow the loudest person","Return the decision to the accountable approver","Make two unrelated drafts"],"answer":2,"explain":"Contradictory goals need a decision, not silent compromise."},{"q":"What makes a portfolio sample persuasive?","options":["A famous topic","A brief, process, sources, and finished piece","A long biography","A low rate card"],"answer":1,"explain":"Clients hire visible judgment and a repeatable process."}],"glossary":[{"term":"Brief","def":"The agreed reader, goal, constraints, sources, and approval path."},{"term":"Search intent","def":"The problem a person is trying to solve with a query."},{"term":"Primary source","def":"Original evidence such as an interview, document, customer call, or data set."},{"term":"Angle","def":"The specific argument or lens that makes a piece useful."},{"term":"Voice sheet","def":"A short record of a brand’s repeatable language choices."},{"term":"CTA","def":"The next action requested from the reader."},{"term":"Evergreen","def":"Content that stays useful beyond a campaign date."},{"term":"Content refresh","def":"Updating an existing piece for accuracy, relevance, or performance."},{"term":"Byline","def":"The name credited as author."},{"term":"CMS","def":"The system used to publish content, such as WordPress."},{"term":"Suggesting mode","def":"A review mode that shows changes instead of silently applying them."},{"term":"Style guide","def":"Rules for grammar, terminology, tone, and formatting."}]};

